{
  "name": "00-Common-Setup",
  "expect": "system running, reset, normal values -> vote OK, no alarm"
}

{
  "name": "01-Normal-Operation",
  "expect": "heater ON <22 C / OFF >24 C, fan ON >28 C or >85 %, pump ON <35 % / OFF >50 %, heater hysteresis"
}

{
  "name": "F1-WrongValue",
  "expect": "T2 +15 C -> voter MASKED, real temperature used, NO false alarm; recovers after repair"
}

{
  "name": "F2-DeadSensor",
  "expect": "T3 dead -> watchdog T3 FAILED within 2.5 s (RT3), voter DEGRADED (2 sensors); recovers after repair"
}

{
  "name": "F3-SafeState",
  "expect": "T3 dead + T1 wrong -> no agreement -> SAFE STATE (heater OFF, fan ON, alarm ON); leaves it after repair"
}

{
  "name": "F4-RaceCondition",
  "expect": "unsafe counter LOSES updates, synchronized and AtomicInteger = 200000"
}

{
  "name": "F5-HeatWave",
  "expect": "+14 C -> Observe & React: alarm + fan ON within 1 s (RT2)"
}

{
  "name": "X1-InvalidInputs",
  "expect": "every wrong input REJECTED (400/404/405), system state unchanged"
}

{
  "name": "X2-StuckAndImpossibleValue",
  "expect": "stuck T1 out-voted (MASKED); impossible 115 C reading rejected -> DEGRADED"
}

{
  "name": "X3-HumiditySoilFailure",
  "expect": "S1 dead -> pump OFF; H1 dead -> fan ON; repeated warnings; recovery after repair"
}

{
  "name": "X4-MixedChaos",
  "expect": "mixed valid/invalid inputs, faults, exception, heat wave -> never crashes, recovers fully"
}

{
  "name": "03-Timing-And-Shutdown",
  "expect": "timing table: total U <= 0.757 -> SCHEDULABLE; clean shutdown"
}
